const AD = "499645fc653f159a8aa17b06d0d86fb034643969";
const S22 = `(select id from session where project_id='${AD}' and version='1.18.22')`;

// mask anything that looks like a live credential value before printing
const mask = (s) => s
  .replace(/(gh[pousr]_|github_pat_)[A-Za-z0-9_]{10,}/g, '$1<MASKED>')
  .replace(/sk-[A-Za-z0-9-]{15,}/g, 'sk-<MASKED>')
  .replace(/[A-Za-z0-9+/]{40,}={0,2}/g, '<MASKED-B64>');

function ctx(text, needle, w = 70) {
  const i = text.indexOf(needle);
  if (i < 0) return '';
  return mask(text.slice(Math.max(0, i - w), i + needle.length + w)).replace(/\s+/g, ' ');
}

for (const n of ['github_pat','ghp_','api_key','ACCESS_TOKEN','refresh_token','password']) {
  const rows = q(`select id, json_extract(data,'$.tool') tool, json_extract(data,'$.type') type, data from part where session_id in ${S22} and data like '%${n}%' limit 3`);
  console.log(`\n===== ${n} (${rows.length} shown) =====`);
  for (const r of rows) console.log(` [${r.type}/${r.tool}] ${ctx(r.data, n)}`);
}

console.log('\n\n===== ERW hits: which tools, which sessions =====');
console.log(JSON.stringify(q(`select json_extract(data,'$.type') type, json_extract(data,'$.tool') tool, count(*) n from part where session_id in ${S22} and data like '%ERW%' group by type, tool order by n desc`)));
const erw = q(`select id, json_extract(data,'$.type') type, json_extract(data,'$.tool') tool, data from part where session_id in ${S22} and data like '%ERW%' limit 6`);
for (const r of erw) console.log(` [${r.type}/${r.tool}] ${ctx(r.data,'ERW',90)}`);
db.close();
