import { DatabaseSync } from 'node:sqlite';
import os from 'node:os';
import path from 'node:path';
const db = new DatabaseSync(path.join(os.homedir(),'.local','share','opencode','opencode.db'), { readOnly: true });
const q = (sql) => db.prepare(sql).all();
const AD = "499645fc653f159a8aa17b06d0d86fb034643969";
const S22 = `(select id from session where project_id='${AD}' and version='1.18.22')`;

// GLOB is case-SENSITIVE in SQLite
const needles = ['ERW','ghp_*','github_pat_*','sk-ant-*','AKIA*','xox?-*'];
for (const n of needles) {
  const pat = n.includes('*') ? `*${n}` : `*${n}*`;
  const p = q(`select count(*) c from part where session_id in ${S22} and data glob '${pat}'`)[0].c;
  const m = q(`select count(*) c from message where session_id in ${S22} and data glob '${pat}'`)[0].c;
  const e = q(`select count(*) c from event where aggregate_id in ${S22} and data glob '${pat}'`)[0].c;
  console.log(`GLOB ${n}: part=${p} message=${m} event=${e}`);
}

console.log('\n--- case-sensitive ERW hits, by tool ---');
console.log(JSON.stringify(q(`select json_extract(data,'$.type') type, json_extract(data,'$.tool') tool, count(*) n from part where session_id in ${S22} and data glob '*ERW*' group by type, tool order by n desc`)));

const rows = q(`select id, json_extract(data,'$.type') type, json_extract(data,'$.tool') tool, data from part where session_id in ${S22} and data glob '*ERW*' limit 8`);
for (const r of rows) {
  const i = r.data.indexOf('ERW');
  console.log(`\n [${r.type}/${r.tool}] ...${r.data.slice(Math.max(0,i-120), i+120).replace(/\s+/g,' ')}...`);
}

// projects siblings other than agent-deck
console.log('\n--- other projects/<project> paths mentioned (case-sensitive) ---');
const set = new Map();
for (const r of q(`select data from part where session_id in ${S22} and data glob '*projects*'`)) {
  for (const m of r.data.matchAll(/projects[\\/]{1,2}([A-Za-z0-9_.-]+)/g)) set.set(m[1], (set.get(m[1])||0)+1);
}
console.log(JSON.stringify([...set.entries()].sort((a,b)=>b[1]-a[1])));
db.close();
EOF
